import React, { useState } from 'react';
import API from '../api/axiosClient';
import { useNavigate, Link } from 'react-router-dom';
import { FaUserPlus, FaEnvelope, FaLock, FaUser, FaEye, FaEyeSlash } from 'react-icons/fa';

export default function Register({ orgId }) {
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [role, setRole] = useState('customer');
    const [error, setError] = useState('');
    const navigate = useNavigate();

    const handleRegister = async (e) => {
        e.preventDefault();
        setError('');

        try {
            await API.post(`/auth/${orgId}/register`, { name, email, password, role });
            navigate('/login');
        } catch (err) {
            setError(err.response?.data?.error || 'Registration failed');
        }
    };

    return (
        <div className="max-w-md mx-auto bg-gray-800 p-8 rounded-xl border border-gray-700 shadow-xl mt-12 text-white">
            <h2 className="text-2xl font-bold mb-6 text-center flex items-center justify-center gap-2">
                <FaUserPlus className="text-emerald-400" /> Create Account
            </h2>

            {error && (
                <div className="mb-4 p-3 bg-red-950 border border-red-700 rounded-lg text-sm text-red-200">
                    {error}
                </div>
            )}

            <form onSubmit={handleRegister} className="space-y-4">
                <div>
                    <label className="block text-sm text-gray-400 mb-1 flex items-center gap-1">
                        <FaUser /> Full Name
                    </label>
                    <input 
                        type="text" 
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                        required
                    />
                </div>
                <div>
                    <label className="block text-sm text-gray-400 mb-1 flex items-center gap-1">
                        <FaEnvelope /> Email
                    </label>
                    <input 
                        type="email" 
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                        required
                    />
                </div>
                <div>
                    <label className="block text-sm text-gray-400 mb-1 flex items-center gap-1">
                        <FaLock /> Password
                    </label>
                    <div className="relative flex items-center">
                        <input 
                            type={showPassword ? 'text' : 'password'} 
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full p-3 pr-12 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                            required
                        />
                        <button 
                            type="button" 
                            onClick={() => setShowPassword(!showPassword)}
                            className="absolute right-3 text-gray-400 hover:text-white focus:outline-none p-1"
                        >
                            {showPassword ? <FaEyeSlash size={18} /> : <FaEye size={18} />}
                        </button>
                    </div>
                </div>
                {/* <div>
                    <label className="block text-sm text-gray-400 mb-1">Role</label>
                    <select 
                        value={role} 
                        onChange={(e) => setRole(e.target.value)}
                        className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                    >
                        <option value="customer">Customer</option>
                        <option value="worker">Worker</option>
                    </select>
                </div> */}
                <button 
                    type="submit"
                    className="w-full bg-emerald-600 hover:bg-emerald-500 p-3 rounded-lg font-semibold transition mt-2"
                >
                    Register
                </button>
            </form>

            <p className="mt-4 text-center text-sm text-gray-400">
                Already have an account? <Link to="/login" className="text-indigo-400 hover:underline">Sign In</Link>
            </p>
        </div>
    );
}
